#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (auto& x : p) scanf("%d", &x);
    string out(n, '0');
    vector<int> mx(n), mn(n);  // monotonic deques stored as index arrays
    for (int k = 1; k <= n; k++) {
        int mxh = 0, mxt = 0, mnh = 0, mnt = 0;
        for (int i = 0; i < n; i++) {
            while (mxt > mxh && p[mx[mxt - 1]] <= p[i]) mxt--;
            mx[mxt++] = i;
            while (mnt > mnh && p[mn[mnt - 1]] >= p[i]) mnt--;
            mn[mnt++] = i;
            if (mx[mxh] <= i - k) mxh++;
            if (mn[mnh] <= i - k) mnh++;
            // Distinct values in a window of size k form {1..k} iff min is 1 and max is k.
            if (i >= k - 1 && p[mx[mxh]] == k && p[mn[mnh]] == 1) { out[k - 1] = '1'; break; }
        }
    }
    puts(out.c_str());
}

