package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := next()
	p := make([]int, n)
	for i := range p {
		p[i] = next()
	}
	out := make([]byte, n)
	for i := range out {
		out[i] = '0'
	}
	mx, mn := make([]int, n), make([]int, n) // monotonic deques stored as index arrays
	for k := 1; k <= n; k++ {
		mxh, mxt, mnh, mnt := 0, 0, 0, 0
		for i := 0; i < n; i++ {
			for mxt > mxh && p[mx[mxt-1]] <= p[i] {
				mxt--
			}
			mx[mxt] = i
			mxt++
			for mnt > mnh && p[mn[mnt-1]] >= p[i] {
				mnt--
			}
			mn[mnt] = i
			mnt++
			if mx[mxh] <= i-k {
				mxh++
			}
			if mn[mnh] <= i-k {
				mnh++
			}
			// Distinct values in a window of size k form {1..k} iff min is 1 and max is k.
			if i >= k-1 && p[mx[mxh]] == k && p[mn[mnh]] == 1 {
				out[k-1] = '1'
				break
			}
		}
	}
	fmt.Println(string(out))
}
